const base = env.get('GREENCORE_API_URL');
const token = env.get('NODE_RED_SHARED_SECRET');
if (!base || !token) { node.error('Set GREENCORE_API_URL and NODE_RED_SHARED_SECRET in Node-RED environment'); return null; }
msg.method = 'GET';
msg.url = base.replace(/\\/$/, '') + '/api/v1/notifications/node-red/pending';
msg.headers = { 'X-Node-RED-Token': token, 'Accept': 'application/json' };
return msg;

const base = env.get('GREENCORE_API_URL');
const token = env.get('NODE_RED_SHARED_SECRET');
const event = msg.payload;
if (!base || !token || !event || !event.id) return null;
msg.method = 'POST';
msg.url = base.replace(/\\/$/, '') + '/api/v1/notifications/node-red/process/' + encodeURIComponent(event.id);
msg.headers = { 'X-Node-RED-Token': token, 'Content-Type': 'application/json' };
msg.payload = {};
return msg;
